add_action( 'woocommerce_after_shop_loop_item', 'perfectpixel_already_purchased_notice', 15 );
add_action( 'woocommerce_single_product_summary', 'perfectpixel_already_purchased_notice', 11 );

function perfectpixel_already_purchased_notice() {
	global $product;
	if ( ! $product || ! is_user_logged_in() ) {
		return;
	}
	$user = wp_get_current_user();
	if ( wc_customer_bought_product( $user->user_email, $user->ID, $product->get_id() ) ) {
		echo '<p class="perfectpixel-already-bought" style="margin:.5em 0;font-size:.9em;color:#00a32a">' . esc_html( '{{already_bought_text}}' ) . '</p>';
	}
}
